import asyncio
import functools
import inspect
from fastapi.dependencies.models import Dependant

def is_coroutine_function(func):
    try:
        return asyncio.iscoroutinefunction(func)
    except Exception:
        return False

def is_generator_function(func):
    return inspect.isgeneratorfunction(func)

def is_async_generator_function(func):
    return inspect.isasyncgenfunction(func)

async def async_func():
    pass

def sync_func():
    pass

def gen_func():
    yield 1

async def async_gen_func():
    yield 1

# Test cases
test_cases = [
    ("async_func", async_func, True, False, False),
    ("sync_func", sync_func, False, False, False),
    ("gen_func", gen_func, False, True, False),
    ("async_gen_func", async_gen_func, False, False, True),
    ("wrapped_async", functools.wraps(sync_func)(async_func), True, False, False),
    ("partial_async", functools.partial(async_func), True, False, False),
    ("wrapped_partial_async", functools.wraps(sync_func)(functools.partial(async_func)), True, False, False),
    ("partial_wrapped_async", functools.partial(functools.wraps(sync_func)(async_func)), True, False, False),
    ("partial_wrapped_partial_async", functools.partial(functools.wraps(sync_func)(functools.partial(async_func))), True, False, False),
]

for name, func, expected_coro, expected_gen, expected_async_gen in test_cases:
    dep = Dependant(call=func)
    coro = dep.is_coroutine_callable
    gen = dep.is_gen_callable
    async_gen = dep.is_async_gen_callable
    print(f"{name}: coro={coro==expected_coro}, gen={gen==expected_gen}, async_gen={async_gen==expected_async_gen}")
    if coro != expected_coro or gen != expected_gen or async_gen != expected_async_gen:
        print(f"  FAILED: expected ({expected_coro}, {expected_gen}, {expected_async_gen}), got ({coro}, {gen}, {async_gen})")

class AsyncCallable:
    async def __call__(self):
        pass

class SyncCallable:
    def __call__(self):
        pass

class GenCallable:
    def __call__(self):
        yield 1

class AsyncGenCallable:
    async def __call__(self):
        yield 1

class CallableTests:
    def __init__(self):
        self.cases = [
            ("AsyncCallable", AsyncCallable(), True, False, False),
            ("SyncCallable", SyncCallable(), False, False, False),
            ("GenCallable", GenCallable(), False, True, False),
            ("AsyncGenCallable", AsyncGenCallable(), False, False, True),
        ]

for name, obj, expected_coro, expected_gen, expected_async_gen in CallableTests().cases:
    dep = Dependant(call=obj)
    coro = dep.is_coroutine_callable
    gen = dep.is_gen_callable
    async_gen = dep.is_async_gen_callable
    print(f"{name}: coro={coro==expected_coro}, gen={gen==expected_gen}, async_gen={async_gen==expected_async_gen}")
    if coro != expected_coro or gen != expected_gen or async_gen != expected_async_gen:
        print(f"  FAILED: expected ({expected_coro}, {expected_gen}, {expected_async_gen}), got ({coro}, {gen}, {async_gen})")

